window.RP_SESSION={"id":"S-8271da2ceb50","messages":[{"id":"RP-III-0011242","time":"2026-01-28T01:34:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"빈센트는 술집 문을 덜컹 열고 들어간다. 구석에서 술을 들이마시던 그는 역시 혼자라 심심한건지 누구를 불러 같이 마시기로 결정했다. 그리고 그 누구는 마리아 아나이스였다. 그녀가 금주라는 걸 알지만 신경 안 쓰는 듯하다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011243","time":"2026-01-28T01:35:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 제가 금주라고 몇 번을 말씀드려요 빈센트 씨... 말동무라도 해드리면 되는 걸까요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011244","time":"2026-01-28T01:36:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“헤헤~ 오늘은 제가 숨겨둔 비상금으로 술 사드릴게요, 그러니까 같이 마셔요~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011245","time":"2026-01-28T01:37:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“안 마셔주면 혼자 쓸쓸해서 이거 참 고독해서 어째~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011246","time":"2026-01-28T01:40:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n주위 두리번...\n\n\"..좋습니다.. 하루만 같이 마셔드리죠.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011247","time":"2026-01-28T01:43:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“탁월한 선택이에요!”\n\n그는 술을 몇잔 더 주문하고선 조잘조잘 떠들어대기 시작했다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011248","time":"2026-01-28T01:45:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"술이 들어가서인가, 이야기가 즐거운 것인가... 나름 잘 들어줍니다.\n\n마리아가 웬일..?\n\n\"그래서,.. 그 여자가 사기를 치고 가서 어떻게 됐다고요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011249","time":"2026-01-28T01:46:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“진짜 어이없다니까요?? 사기 안 쳤어도 돈이 없긴 하지만…”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011250","time":"2026-01-28T01:47:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"오호...~\"\n\n술을 꼴깍꼴깍 들이킵니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011251","time":"2026-01-28T01:49:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“진짜 짜증난다니깐.”\n\n술잔을 들이 마신다. 술이 더 들어갈 수 록 말 수가 더 많아진다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011252","time":"2026-01-28T01:50:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..자자~ 진정하고. 어디 취한김에 노래 한 곡 뽑아봐요\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011253","time":"2026-01-28T01:53:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"”뭐야, 내 노래가 듣고 싶은거에요? 이거 참 바드로서 안 해줄 수 가 없는 부탁이네~“\n\n술에 거하게 취했는지 음을 반 쯤 흘리고 노래 한다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011254","time":"2026-01-28T01:53:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":".....노래가 뭔가 잘못된것같지만 일단 호응해줬다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011255","time":"2026-01-28T01:54:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011256","time":"2026-01-28T01:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 3 = 3\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0011257","time":"2026-01-28T01:54:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"...표정이 다 드러난 모냥이다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011258","time":"2026-01-28T01:55:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“얼굴 썩은게 너무 잘 보이는거 아니에요? 푸하하!”\n\n기분이 나빠지기는 커녕 오히려 재밌는 듯이 웃음을 터뜨린다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011259","time":"2026-01-28T01:55:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ아하하...... 그정도였어요??\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011260","time":"2026-01-28T01:57:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“네에, 너무 잘 드러났어요.”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011261","time":"2026-01-28T01:57:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“이런 얼굴을 받다니이~ 너무나 슬퍼서 눈물이 나올 지경이야.“","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011262","time":"2026-01-28T01:59:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ에에에???\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011263","time":"2026-01-28T01:59:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"잔뜩 당황한듯 어버버 거리는 그녀였다","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011264","time":"2026-01-28T01:59:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㄱ그럴 의도는 없었는데..!!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011265","time":"2026-01-28T02:00:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“하하핳-! 반응 진짜 재밌네요! 완전 리액션 부자네~”\n\n마리아가 제대로 낚인 걸 보고 다시 웃음이 터져나왔다.","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011266","time":"2026-01-28T02:01:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ에에..!! 놀랐잖아요!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011267","time":"2026-01-28T02:06:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“진짜 쉽게 속으시네요~…”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011268","time":"2026-01-28T02:06:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“너무 많이 마셨나, 잠이 다 오네…”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011269","time":"2026-01-28T02:07:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..취해서 그런거에요.. 원래는 잘 안그런다구요.\"\n\n그러면서 또 들이킨다.\n\n\"에휴... 오늘은 외박해야겠어요..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011270","time":"2026-01-28T02:11:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“외박해도 괜찮아요? 돈 많나보네~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011271","time":"2026-01-28T02:12:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“부럽다~ 얼마나 돈이 많으면 외박을! 밖에서 노숙하시는거면 제가 좋은 장소 알려드리죠!?“","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011272","time":"2026-01-28T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..어머, 제가 길거리 출신이라. 그런건 빠삭하답니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011273","time":"2026-01-28T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"언니께서..그니까 에레모시스씨께서 제가 술마시는걸 안좋아하셔서요\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011274","time":"2026-01-28T02:14:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“오오, 경력직~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011275","time":"2026-01-28T02:14:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"푸흐흣.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011276","time":"2026-01-28T02:16:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“나 참 술 사면 비상금 뚝 떨어져 버리는데 말이야~ 이러다간 밖에서 자다가 납치 당해서 장기가 뜯겨버릴 지도 모르겠는걸~ 누가 방이라도 빌려주면 정말 고마울텐데~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011277","time":"2026-01-28T02:20:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011278","time":"2026-01-28T02:21:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"푸하하핫!!\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011279","time":"2026-01-28T02:22:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“그렇게 웃는 걸 보니 실패한거 같네. 더 술 맥일걸.“","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011280","time":"2026-01-28T02:22:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"“아쉽다~”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011281","time":"2026-01-28T09:05:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..에에.. 그게 아쉬울일이던가요 빈센트씨?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011282","time":"2026-01-28T11:36:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"\"헤헤... 꽤나?\"","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011283","time":"2026-01-28T11:44:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"저 생각보다 잘 안취하거든요! 얼마나 마셨는데요~\"\n\n그러곤 다시 한번 들이킵니다 얼굴은 시뻘건걸 보아하니, 거짓말인듯 하네요","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011284","time":"2026-01-28T13:52:00+09:00","room":"RP III","name":"빈센트","profile":"빈센트","identity":"reviewed","type":"dialogue","body":"술자리가 끝나갈 즈음, 계산서를 집어 들었다. 더 앉아 있기엔 머리가 무거워서 자리에서 일어났다.\n\n“전 여기까지만 마시고 이만 가보도록 하죠!”","characters":["P-d2bfdfcba042"]},{"id":"RP-III-0011285","time":"2026-01-28T14:08:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"아, 그럼 일어나죠. 덕분에 오랜만에 진창 마셨네요.\"\n메시지가 삭제되었습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011286","time":"2026-01-28T14:08:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0011287","time":"2026-01-28T14:08:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
